def find_golomb_ruler(n, max_length=100):
    marks = [0]
    used_diffs = set()

    def backtrack():
        if len(marks) == n:
            return True
        # Try next mark position
        start = marks[-1] + 1
        # We can set an upper bound based on remaining marks
        # Simple bound: at least start + (n - len(marks)) more positions
        # But we also have max_length
        for pos in range(start, max_length + 1):
            # Check differences with all existing marks
            diffs = []
            valid = True
            for m in marks:
                d = pos - m
                if d in used_diffs:
                    valid = False
                    break
                diffs.append(d)
            if valid:
                marks.append(pos)
                used_diffs.update(diffs)
                if backtrack():
                    return True
                marks.pop()
                for d in diffs:
                    used_diffs.remove(d)
        return False

    if backtrack():
        return marks
    else:
        return None

