def find_langford_desc(n):
    length = 2*n
    seq = [0]*length

    def backtrack(v):
        if v == 0:
            return True
        for i in range(length - v - 1):
            j = i + v + 1
            if seq[i] == 0 and seq[j] == 0:
                seq[i] = v
                seq[j] = v
                if backtrack(v-1):
                    return True
                seq[i] = 0
                seq[j] = 0
        return False

