n = 14
# Build cycle edges
cycle_edges = set()
for i in range(n):
    cycle_edges.add((min(i, (i+1)%n), max(i, (i+1)%n)))

# All possible valid chords (no cycle < 7 by itself)
valid_chords = []
for i in range(n):
    for k in [6, 7, 8]:
        j = (i + k) % n
        if i < j:
            valid_chords.append((i, j))

print(f"Valid chords: {len(valid_chords)}")
print(valid_chords)

def edges_to_adj(edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return adj

def girth(adj):
    # Returns length of shortest cycle, or float('inf') if acyclic
    shortest = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent[v] != u:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < shortest:
                        shortest = cycle_len
    return shortest

def is_colorable(adj, max_colors=4):
    n = len(adj)
    colors = [-1] * n

    def dfs(u):
        for v in adj[u]:
            if colors[v] == -1:
                for c in range(max_colors):
                    ok = True
                    for w in adj[v]:
                        if colors[w] == c:
                            ok = False
                            break
                    if ok:
                        colors[v] = c
                        if dfs(v):
                            return True
                        colors[v] = -1
                return False
            elif colors[v] == colors[u]:
                return False
        return True

    for start in range(n):
        if colors[start] == -1:
            colors[start] = 0
            if not dfs(start):
                return False
    return True

