def has_4cycle(matrix):
    # Check for any 2x2 submatrix of all 1s
    for i1 in range(7):
        for i2 in range(i1+1, 7):
            for j1 in range(7):
                for j2 in range(j1+1, 7):
                    if matrix[i1][j1] and matrix[i1][j2] and matrix[i2][j1] and matrix[i2][j2]:
                        return True
    return False

def has_6cycle(matrix):
    # Build adjacency and check for 6-cycles
    n = 14
    adj = [[] for _ in range(n)]
    for i in range(7):
        for j in range(7):
            if matrix[i][j]:
                u = i
                v = 7 + j
                adj[u].append(v)
                adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    # cycle found
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= 6:
                        return True
    return False

