def is_graphical(seq):
    seq = sorted(seq, reverse=True)
    n = len(seq)
    S = sum(seq)
    if S % 2 != 0:
        return False
    prefix = [0]
    for d in seq:
        prefix.append(prefix[-1] + d)
    for k in range(1, n+1):
        lhs = prefix[k]
        rhs = k*(k-1)
        for i in range(k, n):
            rhs += min(seq[i], k)
        if lhs > rhs:
            return False
    return True

