# Let's also just BFS from each node to find shortest cycle more carefully
def bfs_shortest_cycle_from(start, adj, n):
    dist = {start: 0}
    parent = {start: None}
    q = deque([start])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                parent[v] = u
                q.append(v)
            elif parent[u] != v:
                # cycle found
                return dist[u] + dist[v] + 1
    return float('inf')

