# compute chromatic number by brute force
def chromatic_number(n, adj):
    # try k colors
    for k in range(1, n+1):
        # assign colors 0..k-1
        colors = [-1]*n
        def backtrack(v):
            if v == n:
                return True
            for c in range(k):
                ok = True
                for u in adj[v]:
                    if colors[u] == c:
                        ok = False
                        break
                if ok:
                    colors[v] = c
                    if backtrack(v+1):
                        return True
                    colors[v] = -1
            return False
        if backtrack(0):
            return k, colors
    return n, colors

