# This is a bounded coloring problem.

def find_coloring():
    # Try all assignments? 4^15 is too big (about 1 billion). Use backtracking.
    colors = [-1] * 15
    color_sizes = [0] * 4

    # Order vertices by degree descending for pruning
    order = sorted(range(15), key=lambda x: len(adj[x]), reverse=True)

    def backtrack(idx):
        if idx == 15:
            return True
        v = order[idx]
        # Try colors 0..3
        for c in range(4):
            if color_sizes[c] >= 4:
                continue
            # Check adjacency
            conflict = False
            for u in adj[v]:
                if colors[u] == c:
                    conflict = True
                    break
            if conflict:
                continue
            colors[v] = c
            color_sizes[c] += 1
            if backtrack(idx + 1):
                return True
            colors[v] = -1
            color_sizes[c] -= 1
        return False

    if backtrack(0):
        return colors
    else:
        return None

