def find_girth(adj, n):
    # BFS from each node to find shortest cycle
    INF = float('inf')
    best = INF
    for start in range(n):
        dist = {i: -1 for i in range(n)}
        parent = {i: -1 for i in range(n)}
        dist[start] = 0
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent[v] != u:
                    # found a cycle
                    # length = dist[u] + dist[v] + 1
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
    return best if best != INF else None

