def find_empty(grid):
    best_idx = -1
    best_options = None
    for i in range(81):
        if grid[i] != 0:
            continue
        options = []
        for v in range(1, 10):
            if is_valid(grid, i, v):
                options.append(v)
        if not options:
            return i, []  # dead end
        if best_options is None or len(options) < len(best_options):
            best_idx = i
            best_options = options
            if len(options) == 1:
                break
    return best_idx, best_options

