import itertools

n = 14

class GraphBuilder:
    def __init__(self, n):
        self.n = n
        self.edges = []
        self.adj = [[] for _ in range(n)]
        self.colors = [-1] * n

    def add_edge(self, u, v):
        self.edges.append((u, v))
        self.adj[u].append(v)
        self.adj[v].append(u)

    def remove_last_edge(self):
        u, v = self.edges.pop()
        self.adj[u].remove(v)
        self.adj[v].remove(u)

    def shortest_cycle_through_edge(self, u, v):
        """Find shortest cycle containing edge (u,v), or inf if none"""
        # Remove edge temporarily and find shortest path from u to v
        self.adj[u].remove(v)
        self.adj[v].remove(u)

        dist = [-1] * self.n
        parent = [-1] * self.n
        from collections import deque
        q = deque([u])
        dist[u] = 0

        while q:
            x = q.popleft()
            if x == v:
                break
            for y in self.adj[x]:
                if dist[y] == -1:
                    dist[y] = dist[x] + 1
                    parent[y] = x
                    q.append(y)

        # Restore edge
        self.adj[u].append(v)
        self.adj[v].append(u)

        if dist[v] == -1:
            return float('inf')
        return dist[v] + 1

    def girth(self):
        """Compute girth of current graph"""
        best = float('inf')
        for u, v in self.edges:
            c = self.shortest_cycle_through_edge(u, v)
            best = min(best, c)
        return best

    def is_3_colorable(self):
        """Check if current graph is 3-colorable using backtracking"""
        colors = [-1] * self.n

        def can_color(v):
            if v == self.n:
                return True
            if colors[v] != -1:
                return can_color(v + 1)

            for c in range(3):
                ok = True
                for u in self.adj[v]:
                    if colors[u] == c:
                        ok = False
                        break
                if ok:
                    colors[v] = c
                    if can_color(v + 1):
                        return True
                    colors[v] = -1
            return False

        return can_color(0)

    def is_3_colorable_fast(self):
        """Faster check using greedy + backtracking on uncolored vertices"""
        colors = [-1] * self.n

        # Order vertices by degree (descending)
        order = sorted(range(self.n), key=lambda x: len(self.adj[x]), reverse=True)

        def can_color(idx):
            if idx == self.n:
                return True
            v = order[idx]
            if colors[v] != -1:
                return can_color(idx + 1)

            for c in range(3):
                ok = True
                for u in self.adj[v]:
                    if colors[u] == c:
                        ok = False
                        break
                if ok:
                    colors[v] = c
                    if can_color(idx + 1):
                        return True
                    colors[v] = -1
            return False

        return can_color(0)

